// Verify the HMAC Nasaq signed the body with, then parse it.
//
// Same scheme as the WhatsApp workflow: the digest covers the exact bytes
// that were sent, so it is checked against the raw body — re-serialising the
// parsed JSON changes key order and whitespace and the digest with it.

const secret = $env.NASAQ_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('NASAQ_WEBHOOK_SECRET is not set on this n8n instance.');
}

const item = $input.first();

const raw = item.binary && item.binary.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : JSON.stringify(item.json.body || item.json);

const given = (item.json.headers || {})['x-nasaq-signature'] || '';

const encoder = new TextEncoder();
const key = await crypto.subtle.importKey(
  'raw',
  encoder.encode(secret),
  { name: 'HMAC', hash: 'SHA-256' },
  false,
  ['sign'],
);
const signed = await crypto.subtle.sign('HMAC', key, encoder.encode(raw));
const expected =
  'sha256=' +
  Array.from(new Uint8Array(signed))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');

let valid = given.length === expected.length;
if (valid) {
  let diff = 0;
  for (let i = 0; i < given.length; i++) {
    diff |= given.charCodeAt(i) ^ expected.charCodeAt(i);
  }
  valid = diff === 0;
}

return [{ json: { valid, payload: JSON.parse(raw) } }];

// Build the request to Claude.
//
// This node is where the wording of the prompt lives — edit it here, not in
// Nasaq. What comes back has to be exactly the fields Nasaq stores, so the
// response is constrained by a JSON schema rather than asked for politely:
// output_config.format guarantees the first content block is valid JSON of
// that shape, which removes the whole class of "the model wrote a preamble
// before the JSON" failures.

const p = $json.payload || $json;

const objectives = Array.isArray(p.objectives) ? p.objectives.filter(Boolean) : [];

const facts = [
  `المادة: ${p.subject || 'غير محددة'}`,
  `الصف: ${p.grade || 'غير محدد'}`,
  p.unit ? `الوحدة: ${p.unit}` : null,
  `الدرس: ${p.lessonTitle}`,
  objectives.length ? `أهداف المدرسة لهذا الدرس:\n- ${objectives.join('\n- ')}` : null,
].filter(Boolean).join('\n');

const system =
  'أنت معلم سعودي خبير تكتب خطة درس لمعلم زميل، وفق مناهج وزارة التعليم السعودية.\n' +
  'اكتب بالعربية الفصحى، بجُمل قصيرة قابلة للتنفيذ داخل الحصة، وبلا حشو أو عبارات عامة.\n' +
  'اربط كل ما تكتبه بالدرس المذكور تحديدًا — لا بالمادة عمومًا.' +
  (objectives.length
    ? '\nأهداف المدرسة معطاة: اجعل المحتوى خادمًا لها، ولا تعد كتابتها في حقل الأهداف إلا إن طُلب.'
    : '');

const instruction =
  `${facts}\n\n` +
  'اكتب:\n' +
  '- warmUp: تمهيد لا يزيد عن ٣ جمل يربط الدرس بخبرة سابقة للطالب أو بموقف من حياته.\n' +
  '- closure: إغلاق يلخّص أهم نقطتين أو ثلاث في الدرس.\n' +
  '- vocabulary: المصطلحات الأساسية في الدرس مفصولة بفواصل، بلا تعريفات.\n' +
  '- thinkingSkills: مهارات التفكير التي يمارسها الطالب فعلًا في هذا الدرس، مفصولة بفواصل.\n' +
  '- teacherInstructions: ملاحظة عملية واحدة للمعلم — خطأ شائع يتوقعه أو نقطة يركّز عليها.\n' +
  '- objectives: من هدفين إلى أربعة أهداف سلوكية تبدأ بفعل قابل للقياس.\n' +
  '- teachingStrategies: من استراتيجيتين إلى أربع مناسبة لهذا الدرس.\n' +
  '- teachingAids: من وسيلتين إلى أربع متاحة في فصل عادي.';

const text = { type: 'string' };
const list = { type: 'array', items: { type: 'string' } };

return [
  {
    json: {
      model: $env.NASAQ_AI_MODEL || 'claude-opus-5',
      max_tokens: 4000,
      // Routine writing, not a hard problem: low effort keeps the cost and
      // the latency down. Raise it in the env var if the output is thin.
      output_config: {
        effort: $env.NASAQ_AI_EFFORT || 'low',
        format: {
          type: 'json_schema',
          schema: {
            type: 'object',
            properties: {
              warmUp: text,
              closure: text,
              vocabulary: text,
              thinkingSkills: text,
              teacherInstructions: text,
              objectives: list,
              teachingStrategies: list,
              teachingAids: list,
            },
            required: [
              'warmUp',
              'closure',
              'vocabulary',
              'thinkingSkills',
              'teacherInstructions',
              'objectives',
              'teachingStrategies',
              'teachingAids',
            ],
            additionalProperties: false,
          },
        },
      },
      system,
      messages: [{ role: 'user', content: instruction }],
    },
  },
];

// Pull the JSON out of the response and hand Nasaq exactly its own fields.
//
// output_config.format guarantees the first text block is valid JSON of the
// requested shape, so this is a parse rather than an extraction — but the
// refusal check comes first: a decline arrives as HTTP 200 with
// stop_reason 'refusal' and no usable content, and reading content blindly
// would surface it as a confusing parse error.

const r = $json;

if (r.stop_reason === 'refusal') {
  throw new Error('رفض النموذج توليد المحتوى لهذا الدرس.');
}

const block = (r.content || []).find((b) => b.type === 'text');
if (!block || !block.text) {
  throw new Error('لم يرجع النموذج أي نص.');
}

let data;
try {
  data = JSON.parse(block.text);
} catch (error) {
  throw new Error('رد النموذج ليس JSON صالحًا: ' + String(block.text).slice(0, 120));
}

const str = (v) => (typeof v === 'string' ? v.trim() : '');
const arr = (v) => (Array.isArray(v) ? v.map(str).filter(Boolean) : []);

return [
  {
    json: {
      warmUp: str(data.warmUp),
      closure: str(data.closure),
      vocabulary: str(data.vocabulary),
      thinkingSkills: str(data.thinkingSkills),
      teacherInstructions: str(data.teacherInstructions),
      objectives: arr(data.objectives),
      teachingStrategies: arr(data.teachingStrategies),
      teachingAids: arr(data.teachingAids),
    },
  },
];
